import {parseCSV} from './core.mjs';
let pdfPromise,xlsxPromise,ocrWorker,ocrPromise;
const base=path=>new URL(path,import.meta.url).href;
export async function documentFormat(file){const signature=new TextDecoder('latin1').decode(await file.slice(0,8).arrayBuffer());if(signature.startsWith('%PDF-'))return 'pdf';return file.name.split('.').at(-1).toLowerCase()}
export const supportedFile=name=>/\.(pdf|xlsx?|csv|tsv|txt|eml|png|jpe?g|webp)$/i.test(name);
export function pdfText(items){let text='',lastY=null;for(const item of items){if(!('str'in item))continue;const y=item.transform?.[5];if(lastY!==null&&y!==undefined&&Math.abs(y-lastY)>3&&!text.endsWith('\n'))text+='\n';text+=item.str+(item.hasEOL?'\n':' ');lastY=y}return text.trim()}
export function pdfLayoutText(items){const rows=[];for(const item of items){if(!item.str?.trim())continue;const y=item.transform?.[5]??0;let row=rows.find(r=>Math.abs(r.y-y)<3);if(!row){row={y,items:[]};rows.push(row)}row.items.push(item)}return rows.sort((a,b)=>b.y-a.y).map(r=>r.items.sort((a,b)=>(a.transform?.[4]??0)-(b.transform?.[4]??0)).map(i=>i.str).join(' ')).join('\n');}
async function pdfLibrary(){pdfPromise??=import('./vendor/pdf/pdf.min.mjs');const pdf=await pdfPromise;pdf.GlobalWorkerOptions.workerSrc=base('./vendor/pdf/pdf.worker.min.mjs');return pdf}
async function spreadsheetLibrary(){xlsxPromise??=import('./vendor/xlsx.mjs');return xlsxPromise}
async function loadOCR(){if(globalThis.Tesseract)return globalThis.Tesseract;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=base('./vendor/ocr/tesseract.min.js');s.onload=resolve;s.onerror=()=>{s.remove();reject(Error('No es pot carregar el lector d’imatges. Torna-ho a provar.'))};document.head.append(s)});return globalThis.Tesseract}
async function recognize(image,progress){if(!ocrPromise){ocrPromise=(async()=>{const T=await loadOCR();ocrWorker=await T.createWorker('eng',1,{workerPath:base('./vendor/ocr/worker.min.js'),corePath:base('./vendor/ocr/core'),langPath:base('./vendor/tessdata'),workerBlobURL:false,logger:m=>{if(m.status==='recognizing text')progress?.(`Llegint imatge · ${Math.round(m.progress*100)}%`)}});return ocrWorker})().catch(e=>{ocrPromise=null;throw e})}const worker=await ocrPromise;const result=await worker.recognize(image);return result.data.text}
export async function releaseOCR(){if(ocrWorker)await ocrWorker.terminate();ocrWorker=null;ocrPromise=null}
function abortIf(signal){if(signal?.aborted)throw new DOMException('Lectura aturada','AbortError')}
export async function extractDocument(file,{progress=()=>{},signal,ocr=true}={}){if(file.size>30*1024*1024)throw Error('El document supera els 30 MB. Divideix-lo o associa’l manualment.');const ext=await documentFormat(file);const warnings=[];abortIf(signal);if(['txt','eml','csv','tsv'].includes(ext)){const text=await file.text();const tables=['csv','tsv'].includes(ext)?[parseCSV(text)]:[];return {text,tables,warnings,method:'text'}}if(['xlsx','xls'].includes(ext)){const XLSX=await spreadsheetLibrary(),book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false,sheetRows:2001});const tables=[];let text='';for(const name of book.SheetNames.slice(0,20)){const rows=XLSX.utils.sheet_to_json(book.Sheets[name],{header:1,raw:false,defval:''});tables.push(rows);text+=`\n${name}\n`+rows.map(r=>r.join(' | ')).join('\n');if(rows.length>=2001)warnings.push(`El full ${name} supera les 2.000 files; la lectura és parcial.`)}if(book.SheetNames.length>20)warnings.push('S’han llegit només els primers 20 fulls.');return {text,tables,warnings,method:'Excel'}}if(ext==='pdf'){const pdfjs=await pdfLibrary();const loading=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,cMapUrl:base('./vendor/pdf/cmaps/'),cMapPacked:true,standardFontDataUrl:base('./vendor/pdf/standard_fonts/'),wasmUrl:base('./vendor/pdf/wasm/')});let pdf;let text='',layoutText='',ocrPages=0;try{pdf=await loading.promise;const limit=Math.min(pdf.numPages,40);if(pdf.numPages>limit)warnings.push(`S’han llegit ${limit} de ${pdf.numPages} pàgines. La lectura és parcial.`);for(let n=1;n<=limit;n++){abortIf(signal);progress(`Llegint pàgina ${n} de ${limit}`);const page=await pdf.getPage(n);const pageItems=(await page.getTextContent()).items;let content=pdfText(pageItems);layoutText+=`\n${pdfLayoutText(pageItems)}\n`;if(content.replace(/\s/g,'').length<35){if(ocr&&ocrPages<10&&typeof document!=='undefined'){progress(`Llegint escaneig · pàgina ${n}`);const raw=page.getViewport({scale:1}),scale=Math.min(2,2200/Math.max(raw.width,raw.height));const viewport=page.getViewport({scale}),canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);try{await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;content=await recognize(canvas,progress);ocrPages++;}finally{canvas.width=0;canvas.height=0}}else warnings.push(`Pàgina ${n}: sense text llegible${ocrPages>=10?' (límit de 10 pàgines escanejades)':''}.`)}text+=`${n>1?'\f':''}\n${content}\n`;page.cleanup();if(text.length>250000){warnings.push('Document molt llarg: text limitat a 250.000 caràcters.');text=text.slice(0,250000);break}}return {text,layoutText:layoutText.slice(0,250000),tables:[],warnings,method:ocrPages?'PDF + lectura d’imatge':'PDF'}}catch(e){if(e.name==='PasswordException')throw Error('El PDF està protegit amb contrasenya. Desprotegeix-ne una còpia o associa’l manualment.');throw e}finally{await loading.destroy()}}if(['png','jpg','jpeg','webp'].includes(ext)){if(!ocr)throw Error('Cal lectura d’imatge per a aquest document.');progress('Llegint el text de la imatge…');const bitmap=await createImageBitmap(file);const scale=Math.min(1,2500/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));try{canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);return {text:await recognize(canvas,progress),tables:[],warnings:['Text llegit d’una imatge: comprova especialment els noms i els horaris.'],method:'Lectura d’imatge'}}finally{bitmap.close();canvas.width=0;canvas.height=0}}throw Error('Format no compatible amb la lectura. Pots associar-lo manualment.')}
